const hits = await glob({ pattern: "node_modules/**/vitest/package.json" });
const vd = await glob({ pattern: "node_modules/.vitest*/**" });
return { hits: hits.slice(0,20), count: hits.length, vd: vd.slice(0,10) };

const files = await glob({ pattern: ".agent/runs/**/*vitest.config*" });
const out = [];
for (const f of files) {
  const t = await read(f);
  out.push({ f, hasChdir: t.includes('chdir'), hasThreads: t.includes("pool: 'threads'"), hasIsolate: t.includes('isolate: false') });
}
return out;

